window.search = Object.assign(window.search, JSON.parse('{"results_options":{"limit_results":30,"teaser_word_count":30},"search_options":{"bool":"OR","expand":true,"fields":{"body":{"boost":1},"breadcrumbs":{"boost":1},"title":{"boost":2}}},"doc_urls":["intro.html","people.html#народ"],"index":{"fields":["title","body","breadcrumbs"],"pipeline":["trimmer","stopWordFilter","stemmer"],"ref":"id","version":"0.9.5","index":{"body":{"root":{"docs":{},"df":0}},"breadcrumbs":{"root":{"docs":{},"df":0}},"title":{"root":{"docs":{},"df":0}}},"documentStore":{"save":true,"docs":{"0":{"body":"Обект на нашето изследване е държавата; предмет на нашата наука са законите, по които държавата се явява, живее, променя се и изчезва. Общото учение за държавата е теоретична, обяснителна и нормативна духовна наука. Тя е теоретична, защото дири и установява трайните закони на държавния живот; тя е обяснителна, защото ни открива каузалната (причинната) връзка между явленията; тя е нормативна, защото ни сочи целите на държавата. Държавата е обединено в народ общество, заседнало на дадена територия и подчинено на една самопроизводна, суверенна и принудителна власт. Любомир Владикин","breadcrumbs":"Увод","id":"0","title":"Увод"},"1":{"body":"Думата народ представлява три различни понятия: население (статистическо понятие) Хората, които населяват дадена държава, включително временно пребиваващи чужденци. народност (културно понятие) Етическа принадлежност, без значение от местоположението. Например българите\\nи на територията на България, и на териториите на поробените земи или разпръснати\\nв други държави. поданство (юридическо понятие) Изключва временно пребиваващите чужденци, но включва поданиците в странство.\\nНапример сред българските поданици попадат различни народности (турци, евреи, арменци и т.н.),\\nкоито знаят, че не са и не се чувстват българи.","breadcrumbs":"Народ » Народ","id":"1","title":"Народ"}},"docInfo":{"0":{"body":0,"breadcrumbs":0,"title":0},"1":{"body":0,"breadcrumbs":0,"title":0}},"length":2},"lang":"English"}}'));